public enum GPV1SubmitCommandEnvelopePayloadCommand: Codable, Equatable, Sendable {
    case assignCharacter(GPV1AssignCharacterCommand)
    case advanceScene(GPV1AdvanceSceneCommand)
    case revealClue(GPV1RevealClueCommand)
    case openVoting(GPV1OpenVotingCommand)
    case castVote(GPV1CastVoteCommand)
    case closeVoting(GPV1CloseVotingCommand)

