        case discriminator = "type"
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: DiscriminatorKeys.self)
        let discriminator = try container.decode(String.self, forKey: .discriminator)
        switch discriminator {
        case "assign_character":
            self = .assignCharacter(try GPV1AssignCharacterCommand.init(from: decoder))
        case "advance_scene":
            self = .advanceScene(try GPV1AdvanceSceneCommand.init(from: decoder))
        case "reveal_clue":
            self = .revealClue(try GPV1RevealClueCommand.init(from: decoder))
        case "open_voting":
            self = .openVoting(try GPV1OpenVotingCommand.init(from: decoder))
        case "cast_vote":
            self = .castVote(try GPV1CastVoteCommand.init(from: decoder))
        case "close_voting":
            self = .closeVoting(try GPV1CloseVotingCommand.init(from: decoder))
        default:
            throw GPContractError.unsupportedVariant(field: "type", value: discriminator)
        }
    }

    public func encode(to encoder: Encoder) throws {
        switch self {
        case .assignCharacter(let value): try value.encode(to: encoder)
        case .advanceScene(let value): try value.encode(to: encoder)
        case .revealClue(let value): try value.encode(to: encoder)
        case .openVoting(let value): try value.encode(to: encoder)
        case .castVote(let value): try value.encode(to: encoder)
        case .closeVoting(let value): try value.encode(to: encoder)
        }
    }
}

